		end = r.max
		extra_star = starBit
	} else {
		start, err = parseIntOrName(lowAndHigh[0], r.names)
		if err != nil {
			return zero, err
		}
		switch len(lowAndHigh) {
		case 1:
			end = start
		case 2:
			end, err = parseIntOrName(lowAndHigh[1], r.names)
			if err != nil {
				return zero, err
			}
		default:
			return zero, fmt.Errorf("Too many hyphens: %s", expr)
		}
	}

